 "same_work": [
  {
   "titles": [
    "ניו-יאָרק פֿאַרטאגס",
    "אין האַרץ פון ניו-יאָרק"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "„ניו-יאָרק פֿאַרטאגס״, (וואָס איז דעם 16 מערץ 1928 געשפּילט געוואָרן אין ליריק-טעאַטער א'נ „אין האַרץ פון ניו-יאָרק״)"
  },
  {
   "titles": [
    "אַמעריקאַנער קינדער",
    "די צעבראָכענע היים",
    "קייטן פֿון ליבע",
    "דעם חזןס טאָכטער"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "„אַמעריקאַנער קינדער“, וואָס איז דעם 13 אַפּריל 1917 געשפּילט געוואָרן אין ליריק-טעאַטער א'נ „די צעבראָכענע היים\" און דעם 20 אָקטאָבער 1923 אין זעלבן טעאַטער א'נ „קייטן פֿון ליבע\". די זעלבע פּיעסע איז אויך ביי אַנדערע געלעגנהייטן געשפּילט געוואָרן א'נ „דעם חזןס טאָכטער“."
  },
  {
   "titles": [
    "מארד ערשטער גראד",
    "לייכטזייניקע מיידלעך"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "„מארד ערשטער גראד“ (געשפּילט געוואָרן דעם 26 נאוועמבער 1926 אין ליריק-טעאַטער א'נ „לייכטזייניקע מיידלעך“)"
  },
  {
   "titles": [
    "מאַן, פרוי און פֿריינט",
    "זינדיקע נשמות"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "„מאַן, פרוי און פֿריינט\" (געשפּילט געוואָרן אויך דעם 2 יולי 1916 אין ליריק-טעאַטער א'נ „זינדיקע נשמות\")"
  },
  {
   "titles": [
    "מיט 8 יאָר צוריק",
    "צעשטערטע חלומות"
   ],
   "author": "SUBJECT",
   "how": "staged in a new revision under another name",
   "evidence": "זיין 5 אַקטיקע פּיעסע „מיט 8 יאָר צוריק\" (געשפּילט געוואָרן דעם 29 נאָוועמבער 1928 אין ליריק-טעאַטער אין אַ נייער באַאַרבעטונג א'נ \"צעשטערטע חלומות״)"
  },
  {
   "titles": [
    "מיין קוזיינע לינא",
    "שכל דאַרף מען האָבן",
    "לינאַ פֿון פּאלעסטינאַ"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "זיין קאָמעדיע „מיין קוזיינע לינא“, וועלכע איז דעם 13 אקטאָבער 1916 געשפּילט געוואָרן אין ברוקלינער ליריק-טעאַטער א'נ „שכל דאַרף מען האָבן״ און דעם 27 סעפּטעמבער 1927 אין מעקינלי-טעאַטער א'נ „לינאַ פֿון פּאלעסטינאַ״"
  },
  {
   "titles": [
    "פֿאַר זיין מוטערס זיינד",
    "דער גאַסן-יונג"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "„פֿאַר זיין מוטערס זיינד“ (וואָס איז דעם 27 נאוועמבער 1924 ווידער אויפֿגעפֿירט געוואָרן אין זעלבן טעאַטער א'נ „דער גאַסן-יונג״)"
  },
  {
   "titles": [
    "2 שוועסטערן",
    "ווען בלינדע זעען"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "ל.'ס \"2 שוועסטערן“, וואָס איז דעם 31 יאַנואַר 1919 אויפֿגעפֿירט געוואָרן דורכן מחבר אין ליריק-טעאַטער א'נ „ווען בלינדע זעען, אין 3 אַקטן מיט פּראָ, לאַג און עפּילאָג\"."
  },
  {
   "titles": [
    "דער פּרייז פֿאַר אַ מיידלס גוד-טיים",
    "אַ קינד אָן אַ היים"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "ל.'ס „דער פּרייז פֿאַר אַ מיידלס גוד-טיים, לעבנסבילד אין 4 אקטן״ וואָס איז אויך געשפּילט געוואָרן א'נ „אַ קינד אָן אַ היים\"."
  },
  {
   "titles": [
    "דאָס האַרץ פון אַ קינד",
    "ערלעכע גנבים",
    "דאָס האַרץ פון אַ טאטען"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "„דאָס האַרץ פון אַ קינד, לעבנסבילד אין 4 אקטן“, וואָס איז שפּעטער אויפֿגעפֿירט געוואָרן דורך יאָזער קעסלער אין מעקינלי-טעאַטער א'נ \"ערלעכע גנבים\" און איז אויך דעם 13 אקטאָבער 1922 אויפֿגעפֿירט געוואָרן אין האָפּקינסאָן-טעאַטער א'נ „דאָס האַרץ פון אַ טאטען\"."
  },
  {
   "titles": [
    "דאָס שטיקינד פֿון דער וועלט",
    "פּרינץ ישראל",
    "יעדער ייד"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "זיין פּיעסע „דאָס שטיקינד פֿון דער וועלט... די זעלבע פּיעסע איז א'נ „פּרינץ ישראל\"... די פּיעסע איז אויך געשפּילט געוואָרן אין אַנדערע טרופּעס א'נ \"יעדער ייד\"."
  },
  {
   "titles": [
    "מיין טאַטענס ווייב",
    "העלא מאַמא",
    "מזל טוב מאַמאַ",
    "האָטעל לעפּקאָוויטש"
   ],
   "author": "SUBJECT",
   "how": "staged in revised forms under other names",
   "evidence": "ל.'ס „מיין טאַטענס ווייב... די זעלבע קאָמעדיע איז אין אַ באַאַרבעטער פֿאַרם אויפֿגעפֿירט געוואָרן... א'נ „העלא מאַמא“, איז שפּעטער געשפּילט געוואָרן א'נ „מזל טוב מאַמאַ“ אין איז... א'נ „האָטעל לעפּקאָוויטש\"."
  },
  {
   "titles": [
    "געקלינט און געפּרעסט",
    "גאַליציאָנער און ליטוואַקעס"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "די קאָמעדיע „געקלינט און געפּרעסט״, וואָס איז דעם 25 סעפּטעמבער 1923 אויפֿגעפֿירט געוואָרן אין ליריק-טעאטער דורכן מחבר א'נ „גאַליציאָנער און ליטוואַקעס, לאַך-קאָמעדיע אין 4 אקטן“"
  },
  {
   "titles": [
    "יעדעס מיידל",
    "דער וועג פֿון יעדעס מיידל"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "זיין ״יעדעס מיידל, אַלעגאָרישע דראַמע מיט מוזיק אין 3 אַקטן מיט אַ פּראָלאָג“... די זעלבע פּיעסע איז דעם 25 נאָוועמבער 1927 געשפּילט געוואָרן אין ניו יאָרקער ליריק-טעאַטער א'נ „דער וועג פֿון יעדעס מיידל״."
  },
  {
   "titles": [
    "אַ מיידלס זיסער חלום",
    "פֿאַר דער חופּה",
    "פאַרלוירן אין געפונען"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "זיין 4-אַקטיקע פּיעסע „אַ מיידלס זיסער חלום\" (וואָס איז אויך געשפּילט געוואָרן אין „פֿאַר דער חופּה\" און „פאַרלוירן אין געפונען“)"
  },
  {
   "titles": [
    "אַ כלה אָן אַ חתן",
    "חתן כלה מזל טוב"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "„אַ כלה אָן אַ חתן“ (מוזיק פֿון א. פּערלמוטער), וואָס איז דעם 8 פעברואר 1929 אין אַ געענדערטער פֿאָרם געשפּילט געוואָרן אין ליריק-טעאַטער א'נ „חתן כלה מזל טוב\""
  },
  {
   "titles": [
    "גאָלדענע ליבע",
    "ליבע צו פֿאַרקויפן"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "די 4-אַקטיקע מעלאָדראַמע „גאָלדענע ליבע\" (וואָס איז דעם 3 פעברואר 1928 געשפּילט געוואָרן אין זעלבן טעאַטער א'נ „ליבע צו פֿאַרקויפן“)"
  },
  {
   "titles": [
    "פאלשע געטער",
    "ליידים פֿון דער נאַכט"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "„פאלשע געטער, לעבנסבילד אין 4 אַקטן, מוזיק פֿון א. פּערלמוטער“ (וואָס איז דעם 1 מאי 1925 געשפּילט געוואָרן אין לענאָקס-טעאַטער א'נ „ליידים פֿון דער נאַכט“)"
  },
  {
   "titles": [
    "וואו איז מיין ווייג",
    "דאָס יידל פֿון דער סאוט"
   ],
   "author": "SUBJECT",
   "how": "staged under another name",
   "evidence": "אויפגעפירט געוואָרן וואו איז מיין ווייג, וואָס איז דעם 2 מערץ 1927 ווידער אויפֿגעפֿירט געוואָרן דורך סעמועל גאָלדענבורג אין נעשאָנאל-טעאַטער א'נ „דאָס יידל פֿון דער סאוט“"
  },
  {
